// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Temel muhasebe ve finansal tablo analizi: bilanço eşitliği, gelir tablosu, cari oran, kârlılık marjları, amortisman ve başabaş noktası (kolay).
const ozEconomics18Kolay = <(String, String, List<String>, String)>[
  ('Muhasebede bir işletmenin sahip olduğu tüm ekonomik değerler ile bunların finansman kaynakları arasındaki temel dengeyi ifade eden eşitlik aşağıdakilerden hangisidir?', 'Varlıklar = Yabancı Kaynaklar + Özkaynaklar', ['Varlıklar = Dönen Varlıklar + Kısa Vadeli Borçlar', 'Özkaynaklar = Varlıklar + Uzun Vadeli Yabancı Kaynaklar', 'Yabancı Kaynaklar = Dönen Varlıklar + Duran Varlıklar'], 'Temel muhasebe eşitliğine göre işletmenin tüm varlıkları, borçlar (yabancı kaynaklar) ve ortakların koyduğu sermaye (özkaynaklar) toplamına eşittir.'),
  ('Bir işletmenin belirli bir tarihteki varlıklarını ve bu varlıkların sağlandığı kaynakları bir arada gösteren finansal tabloya ne ad verilir?', 'Bilanço', ['Gelir tablosu', 'Nakit akış tablosu', 'Fon akım tablosu'], 'Bilanço (finansal durum tablosu), işletmenin belli bir andaki varlık, borç ve özkaynak yapısını gösteren statik tablodur.'),
  ('Bilançonun sol tarafında yer alan ve işletmenin sahip olduğu nakit, alacak, stok, makine gibi iktisadi kıymetleri kapsayan bölüme ne ad verilir?', 'Aktif', ['Pasif', 'Özkaynak', 'Tahakkuk'], 'Hesap tipi bilançoda sol taraf "aktif" olarak adlandırılır ve işletmenin tüm dönen ve duran varlıklarını içerir.'),
  ('Bilançonun sağ tarafında yer alan ve işletme varlıklarının hangi borçlarla veya sermayeyle finanse edildiğini gösteren bölüme ne ad verilir?', 'Pasif', ['Aktif', 'Mevcutlar', 'Alacaklar'], 'Bilançonun sağ tarafı "pasif" adını alır ve yabancı kaynaklar ile özkaynakların toplamından oluşur.'),
  ('Normal koşullarda bir yıl veya işletmenin normal faaliyet dönemi içinde nakde çevrilmesi, satılması ya da tüketilmesi beklenen varlık grubuna ne ad verilir?', 'Dönen varlıklar', ['Duran varlıklar', 'Özkaynaklar', 'Uzun vadeli yabancı kaynaklar'], 'Bir yıl içinde paraya dönüşmesi veya tüketilmesi öngörülen kasa, banka, ticari mal gibi kalemler dönen varlıkları oluşturur.'),
  ('İşletme faaliyetlerinde bir yıldan daha uzun süre kullanılmak amacıyla edinilen ve kısa vadede satılması düşünülmeyen varlıklar hangi grupta izlenir?', 'Duran varlıklar', ['Dönen varlıklar', 'Kısa vadeli yabancı kaynaklar', 'Hazır değerler'], 'Bina, makine, taşıt, demirbaş ve uzun vadeli alacaklar gibi bir yıldan uzun ömürlü kıymetler duran varlıklar grubunda yer alır.'),
  ('Vadesi bir yıla kadar olan ve işletmenin üçüncü kişilere ödemekle yükümlü bulunduğu borçlar bilançonun hangi ana grubunda yer alır?', 'Kısa vadeli yabancı kaynaklar', ['Uzun vadeli yabancı kaynaklar', 'Dönen varlıklar', 'Özkaynaklar'], 'Bir yıl veya normal faaliyet dönemi içinde ödenmesi gereken tüm borçlar kısa vadeli yabancı kaynaklar altında raporlanır.'),
  ('İşletmenin bankalardan veya diğer kreditörlerden sağladığı ve geri ödeme süresi bir yıldan daha uzun olan borçlar hangi grupta sınıflandırılır?', 'Uzun vadeli yabancı kaynaklar', ['Kısa vadeli yabancı kaynaklar', 'Duran varlıklar', 'Sermaye yedekleri'], 'Vadesi bilançonun düzenlendiği tarihten itibaren bir yılı aşan yükümlülükler uzun vadeli yabancı kaynaklar grubunda izlenir.'),
  ('İşletme sahip veya ortaklarının işletme varlıkları üzerinde yabancı kaynaklar düşüldükten sonra kalan haklarını ifade eden kavram aşağıdakilerden hangisidir?', 'Özkaynaklar', ['Kısa vadeli borçlar', 'Hazır değerler', 'Ticari alacaklar'], 'Temel muhasebe eşitliğinden (Özkaynaklar = Varlıklar - Yabancı Kaynaklar) anlaşılacağı üzere, borçlar çıktıktan sonra kalan net varlık tutarı özkaynaklardır.'),
  ('Aşağıdaki kalemlerden hangisi bir üretim işletmesinin bilançosunda "Dönen Varlıklar" grubunda yer alır?', 'Bankadaki vadesiz mevduat', ['Fabrika üretim binası', 'Üretim hattındaki sanayi robotu', 'Tescilli marka ve patent hakları'], 'Bankadaki vadesiz mevduat anında kullanılabilecek hazır bir değer olduğu için dönen varlıklar grubunun en likit kalemlerindendir.'),
  ('Aşağıdakilerden hangisi bilançoda "Duran Varlıklar" ana grubu içerisinde raporlanan bir unsurdur?', 'Dağıtım faaliyetlerinde kullanılan kamyonet', ['Satılmak üzere depoda bekletilen ticari mallar', 'Müşterilerden alınan üç ay vadeli senetler', 'Kasada bulunan yabancı ülke paraları'], 'İşletme faaliyetlerinde uzun süreli kullanılan taşıtlar (kamyonet vb.) maddi duran varlık niteliğindedir.'),
  ('Bilançoda varlıkların sıralanmasında esas alınan ve bir varlığın değer kaybetmeden hızla nakde dönüşebilme kolaylığını ifade eden kavram hangisidir?', 'Likidite', ['Kârlılık', 'Verimlilik', 'Tahakkuk'], 'Aktif kalemler bilançoda likidite derecesine göre (en likit olandan en az likit olana doğru veya tam tersi) sıralanır.'),
  ('İşletmenin kasasında bulunan ulusal ve yabancı paralar ile bankalardaki vadesiz mevduatlarının yer aldığı dönen varlık alt grubuna ne ad verilir?', 'Hazır değerler', ['Menkul kıymetler', 'Ticari alacaklar', 'Maddi duran varlıklar'], 'Hiçbir değer kaybına uğramadan derhal ödeme aracı olarak kullanılabilen nakit ve benzeri varlıklar "Hazır Değerler" grubunu oluşturur.'),
  ('Fiziksel bir varlığa sahip olmayan ancak işletmeye uzun vadede ekonomik fayda sağlayan telif hakkı, patent, lisans ve yazılım gibi unsurlar hangi grupta sınıflandırılır?', 'Maddi olmayan duran varlıklar', ['Maddi duran varlıklar', 'Diğer dönen varlıklar', 'Gelecek aylara ait giderler'], 'Fiziksel yapısı bulunmayan fakat hukuki veya ekonomik koruma sağlayarak uzun süreli yarar yaratan kıymetler maddi olmayan duran varlıklardır.'),
  ('Maddi duran varlıkların (arsa ve boş arazi hariç) zaman içinde kullanıma ve teknolojik eskimeye bağlı değer kaybını muhasebeleştirmek için ayrılan paya ne denir?', 'Amortisman', ['Reeskont', 'Karşılık', 'Enflasyon düzeltmesi'], 'Bina, makine, taşıt gibi duran varlıkların maliyetinin faydalı ömürleri boyunca giderleştirilmesine amortisman denir.'),
  ('Müşterilere yapılan kredili (veresiye) mal veya hizmet satışlarından doğan ve senebe bağlanmamış olan bir yıldan kısa vadeli alacaklar hangi hesapta izlenir?', 'Alıcılar', ['Satıcılar', 'Alacak senetleri', 'Verilen sipariş avansları'], 'Ana faaliyet konusundan doğan senetsiz ticari alacaklar dönen varlıklar içindeki "Alıcılar" hesabında takip edilir.'),
  ('İşletmenin mal satın almak amacıyla tedarikçisine malı teslim almadan önce yaptığı ön ödeme bilançoda nasıl sınıflandırılır?', 'Dönen varlıklarda (Verilen Sipariş Avansları)', ['Kısa vadeli yabancı kaynaklarda (Alınan Sipariş Avansları)', 'Özkaynaklarda (Ödenmiş Sermaye)', 'Ticari borçlarda (Satıcılar)'], 'Tedarikçiye önceden ödenen avans, işletmeye mal talep etme hakkı veren bir alacak niteliğindedir ve mal teslim alınana kadar varlık olarak izlenir.'),
  ('İşletmenin kendi personeline çalıştıkları ay sonunda henüz ödemediği tahakkuk etmiş ücret ve maaş tutarları bilançoda hangi grupta yer alır?', 'Kısa vadeli yabancı kaynaklar', ['Dönen varlıklar', 'Özkaynaklar', 'Duran varlıklar'], 'Personele ödenecek ücretler işletmenin kısa sürede yerine getirmesi gereken bir yükümlülüğü (borcu) olduğundan kısa vadeli yabancı kaynaklarda izlenir.'),
  ('Aşağıdaki işlemlerden hangisi bilançonun hem aktif hem de pasif toplamını aynı anda büyütür?', 'Bankadan kredi çekerek işletmenin vadesiz mevduat hesabına yatırmak', ['Kasada bulunan nakit parayı işletmenin banka hesabına yatırmak', 'Müşteriden olan senetsiz alacağı tahsil ederek kasaya koymak', 'Ortaklara olan borcu yeni hisse senedi ihraç ederek sermayeye eklemek'], 'Bankadan kredi çekildiğinde mevduat (aktif) ve banka kredisi borcu (pasif) aynı tutarda artar; diğer seçenekler yalnızca aktif veya yalnızca pasif içi yer değiştirmedir.'),
  ('Muhasebede işletmenin sahiplerinden ve yöneticilerinden ayrı, bağımsız bir mali kimliğe sahip olduğunu kabul eden temel kavrama ne ad verilir?', 'Kişilik kavramı', ['Süreklilik kavramı', 'Dönemsellik kavramı', 'İhtiyatlılık kavramı'], 'Kişilik kavramı uyarınca işletmenin varlık ve borçları ortağın kişisel malvarlığından ayrı tutulur; ortağın sermaye koyması bile işletme açısından özkaynak yükümlülüğü olarak izlenir.'),
  ('Bilançonun hazırlanmasında işletmenin faaliyetlerini belirli bir süreye bağlı olmaksızın sonsuza dek sürdüreceği varsayımına dayanan muhasebe kavramı hangisidir?', 'İşletmenin sürekliliği kavramı', ['Parayla ölçülme kavramı', 'Sosyal sorumluluk kavramı', 'Tam açıklama kavramı'], 'Süreklilik kavramı sayesinde duran varlıklar tasfiye (hurda) değeriyle değil, işletmedeki uzun vadeli kullanım değerleri ve maliyet esaslarıyla bilançoda yer alır.'),
  ('Fiziksel olarak çok önemli olsa bile "deneyimli ve sadık yönetim ekibi" gibi unsurların bilançoda varlık olarak gösterilememesinin nedeni hangi temel muhasebe kavramıdır?', 'Parayla ölçülme kavramı', ['Dönemsellik kavramı', 'Tutarlılık kavramı', 'Önemlilik kavramı'], 'Muhasebede yalnızca ortak bir ölçü birimi olan para ile güvenilir biçimde ölçülebilen iktisadi kıymet ve olaylar bilançoya yansıtılabilir.'),
  ('Bir işletmenin 1 yıllık kira bedelini dönem başında peşin ödemesi durumunda, henüz kullanılmamış gelecek aylara ilişkin kira tutarı ödeme anında bilançoda nasıl yer alır?', 'Dönen varlıklarda (Gelecek Aylara Ait Giderler)', ['Kısa vadeli borçlarda (Gider Tahakkukları)', 'Özkaynaklarda (Geçmiş Yıllar Zararları)', 'Maddi duran varlıklarda (Binalar)'], 'Peşin ödenen ancak henüz ilgili dönemi gelmediği için tüketilmemiş kira bedeli, işletmenin mülk sahibinden hizmet alma hakkını gösteren bir varlıktır (dönen varlık).'),
  ('Bilanço ile gelir tablosu arasındaki temel zaman boyutu farkı aşağıdakilerden hangisinde doğru ifade edilmiştir?', 'Bilanço belirli bir andaki anlık finansal durumu (fotoğrafı), gelir tablosu ise belirli bir dönemin faaliyet akışını gösterir', ['Bilanço bir yıllık nakit giriş çıkışlarını, gelir tablosu ise yalnızca kuruluş günündeki sermayeyi gösterir', 'Bilanço gelecek beş yılın bütçe tahminlerini, gelir tablosu ise geçmiş on yılın borç stokunu gösterir', 'Her iki tablo da yalnızca belirli bir takvim günündeki kasa ve banka mevcudunu anlık olarak gösterir'], 'Bilanço stok (statik) kavramlara dayanır ve belli bir tarihteki durumu yansıtır; gelir tablosu ise akım (dinamik) kavramlara dayanır ve iki tarih arasındaki performansı ölçer.'),
  ('Bir işletmenin belirli bir hesap döneminde mal ve hizmet satışlarından elde ettiği toplam hasılata, herhangi bir indirim veya iade düşülmeden önce ne ad verilir?', 'Brüt satışlar', ['Net satış hasılatı', 'Faaliyet dışı gelirler', 'Olağan kâr toplamı'], 'Gelir tablosunun en üst kalemi olan brüt satışlar, satış iadeleri ve iskontoları düşülmeden önceki toplam satış tutarını gösterir.'),
  ('Net satışlardan satılan malın maliyeti (SMM) çıkarıldığında elde edilen ilk kâr kalemi hangisidir?', 'Brüt satış kârı', ['Esas faaliyet kârı', 'Vergi öncesi net kâr', 'Dönem net kârı'], 'Net satışlar ile satılan malın maliyeti arasındaki fark brüt satış kârını (veya zararını) verir.'),
  ('Bir fırının günlük ekmek üretim miktarı artsa da azalsa da her ay ödediği sabit dükkan kirası hangi maliyet türüne örnektir?', 'Sabit maliyet', ['Değişken maliyet', 'Birim işçilik maliyeti', 'Marjinal üretim maliyeti'], 'Üretim hacminden bağımsız olarak kısa dönemde değişmeyen kira gibi giderler sabit maliyettir.'),
  ('Bir tekstil atölyesinde dikilen her gömlek için kullanılan kumaş ve düğme giderleri hangi maliyet grubunda yer alır?', 'Değişken maliyet', ['Sabit genel gider', 'Batık yatırım maliyeti', 'Yıpranma payı gideri'], 'Üretim miktarı arttıkça doğru orantılı olarak artan hammadde giderleri değişken maliyettir.'),
  ('İşletmenin bina, makine ve taşıt gibi duran varlıklarının zamanla aşınması ve eskimesi nedeniyle ayrılan paya ne denir?', 'Amortisman', ['Reeskont tutarı', 'Karşılık gideri', 'Şerefiye bedeli'], 'Maddi duran varlıkların ekonomik ömürleri boyunca giderleştirilen yıpranma payına amortisman denir.'),
  ('Bir ürünün birim satış fiyatından birim değişken maliyet çıkarıldığında kalan ve sabit giderleri karşılamaya yarayan tutara ne ad verilir?', 'Birim katkı payı', ['Birim net kâr', 'Ortalama sabit maliyet', 'Brüt kâr marjı'], 'Birim satış fiyatı eksi birim değişken maliyet farkı birim katkı payını oluşturur.'),
  ('İşletmenin toplam gelirlerinin toplam maliyetlerine tam olarak eşit olduğu, ne kâr ne de zarar edilen üretim düzeyine ne ad verilir?', 'Başabaş noktası', ['Maksimum kâr noktası', 'Kapanma eşiği düzeyi', 'Optimum kapasite sınırı'], 'Toplam gelir ile toplam maliyetin eşitlendiği sıfır kâr noktasına başabaş noktası denir.'),
  ('Stok değerlemede "İlk Giren İlk Çıkar" (FIFO) yöntemi uygulayan bir market, raflardan satılan ürünlerin maliyetini hangi partiden başlatarak hesaplar?', 'En eski alınan partiden', ['En son alınan partiden', 'En yüksek fiyatlı partiden', 'En düşük kaliteli partiden'], 'FIFO yönteminde satılan malların maliyeti depoya ilk giren en eski tarihli stoklardan başlanarak hesaplanır.'),
  ('Gelir tablosunda vergi öncesi kârdan kurumlar veya gelir vergisi karşılığı düşüldükten sonra ulaşılan nihai kalem hangisidir?', 'Dönem net kârı', ['Faaliyet kârı', 'Brüt satış kârı', 'Finansman öncesi kâr'], 'Vergi yükümlülükleri düşüldükten sonra kalan son tutar dönem net kârıdır (veya zararıdır).'),
  ('Müşterilere satılan kusurlu ürünlerin işletmeye geri gönderilmesi gelir tablosunda brüt satışlardan hangi başlık altında indirilir?', 'Satıştan iadeler', ['Satış iskontoları', 'Pazarlama giderleri', 'Genel yönetim giderleri'], 'Müşterilerin geri gönderdiği mallar satıştan iadeler hesabında izlenir ve brüt satışlardan düşülür.'),
  ('Üretim miktarı sıfır olduğunda bile işletmenin katlanmak zorunda olduğu toplam maliyet neye eşittir?', 'Toplam sabit maliyete', ['Toplam değişken maliyete', 'Satılan malın maliyetine', 'Birim katkı payına'], 'Hiç üretim yapılmasa dahi kira, sigorta gibi toplam sabit maliyetler ödenmeye devam eder.'),
  ('Brüt satış kârından araştırma-geliştirme, pazarlama ve genel yönetim giderleri çıkarıldığında hangi kâr kalemine ulaşılır?', 'Faaliyet kârı', ['Dönem net kârı', 'Brüt satış hasılatı', 'Vergi sonrası kâr'], 'Ana faaliyet giderleri brüt kârdan düşüldüğünde esas faaliyet kârına ulaşılır.'),
  ('Satış bedelinin vadesinden önce ödenmesi veya yüksek miktarda alım yapılması nedeniyle alıcıya tanınan fiyat indirimlerine gelir tablosunda ne ad verilir?', 'Satış iskontoları', ['Satıştan iadeler', 'Şüpheli alacak karşılığı', 'Komisyon giderleri'], 'Erken ödeme (kasa) veya miktar (ciro) indirimleri brüt satışlardan satış iskontoları kalemiyle düşülür.'),
  ('Bir dondurma büfesinin sadece yaz aylarında çalıştırdığı saatlik ücretli tezgahtarlara ödediği ücret, çalışma saatine göre değiştiği için hangi maliyet sınıfına girer?', 'Değişken maliyet', ['Sabit kira maliyeti', 'Yıllık amortisman gideri', 'Kuruluş örgütlenme gideri'], 'Çalışılan saat ve satış yoğunluğuyla doğrudan değişen saatlik işçilik ödemeleri değişken maliyettir.'),
  ('Toplam sabit maliyet ile toplam değişken maliyetin toplamı aşağıdakilerden hangisini verir?', 'Toplam maliyeti', ['Brüt satış kârını', 'Toplam katkı payını', 'Esas faaliyet gelirini'], 'Bir işletmenin belirli bir üretim düzeyindeki tüm sabit ve değişken giderlerinin toplamı toplam maliyeti oluşturur.'),
  ('Başabaş noktasının üzerinde satış yapan bir işletmede toplam katkı payı ile toplam sabit maliyet arasındaki ilişki nasıldır?', 'Toplam katkı payı toplam sabit maliyetten büyüktür', ['Toplam katkı payı toplam sabit maliyete tam eşittir', 'Toplam sabit maliyet toplam satış gelirinden büyüktür', 'Toplam katkı payı sıfıra eşitlenerek zarar doğurur'], 'Başabaş noktasında katkı payı sabit maliyete eşittir; bu noktanın üzerinde ise katkı payı sabit maliyeti aşarak kâr yaratır.'),
  ('Stoktaki özdeş malların toplam alım maliyetinin toplam birim sayısına bölünmesiyle birim maliyetin bulunduğu stok değerleme yöntemi hangisidir?', 'Ağırlıklı ortalama maliyet yöntemi', ['İlk Giren İlk Çıkar yöntemi', 'Son Giren İlk Çıkar yöntemi', 'Gerçek parti maliyeti yöntemi'], 'Toplam maliyetin toplam miktara bölünmesiyle tek bir ortalama birim maliyet hesaplanması ağırlıklı ortalama yöntemidir.'),
  ('Bir kargo şirketinin satın aldığı dağıtım kamyoneti için ödediği peşin bedel neden alındığı yılın tamamında doğrudan gider yazılmaz?', 'Birden fazla yıl hizmet vereceği için amortisman yoluyla dönemlere yayılır', ['Taşıt alımları vergi yasalarına göre hiçbir zaman gider olarak kabul edilmez', 'Yalnızca kamyonet hurdaya ayrıldığında tek seferde satış maliyeti yazılır', 'Kamyonet stok kalemi sayıldığı için satılana kadar giderleştirilmesi yasaktır'], 'Dönemsellik ve eşleştirme ilkeleri gereği uzun ömürlü duran varlıkların maliyeti faydalı ömürleri boyunca amortismanla giderleştirilir.'),
  ('Ticari bir işletmede dönem içinde satın alınan malların nakliyesi ve sigortası için alıcı tarafından ödenen bedeller muhasebede hangi kaleme eklenir?', 'Ticari malın alış maliyetine', ['Pazarlama satış giderlerine', 'Finansman faiz giderlerine', 'Satıştan iade indirimlerine'], 'Mal depoya girene kadar yapılan nakliye ve sigorta harcamaları malın alış maliyetine dahil edilir.'),
  ('Bir sinema salonunun tek bir seansta içeride 10 izleyici de olsa 150 izleyici de olsa projeksiyon ve salon ısıtması için katlandığı gider o seans için ne tür bir maliyettir?', 'Sabit maliyet', ['Birim değişken maliyet', 'Satış komisyonu gideri', 'Doğrudan hammadde gideri'], 'Seans açıldığında izleyici sayısından bağımsız olarak katlanılan ısıtma ve gösterim gideri sabit maliyettir.'),
  ('Bir işletmenin dönen varlıklarının kısa vadeli yabancı kaynaklarına bölünmesiyle elde edilen likidite oranı aşağıdakilerden hangisidir?', 'Cari oran', ['Asit-test oranı', 'Nakit karşılama oranı', 'Finansal kaldıraç oranı'], 'Cari oran, dönen varlıkların kısa vadeli borçlara bölünmesiyle bulunur ve işletmenin kısa vadeli borç ödeme gücünü genel düzeyde ölçer.'),
  ('Asit-test (likidite) oranı hesaplanırken dönen varlıklar toplamından stokların düşülmesinin temel nedeni aşağıdakilerden hangisidir?', 'Stokların paraya çevrilme hızının diğer dönen varlıklara göre daha düşük ve belirsiz olması', ['Stokların muhasebe kayıtlarında maddi olmayan duran varlık sınıfında izleniyor olması', 'Stok değerlerinin vergi mevzuatı gereği bilanço dipnotlarında gizli tutulması', 'Stokların kısa vadeli yabancı kaynaklar içerisinde bir borç kalemi sayılması'], 'Stoklar satılmadan ve tahsil edilmeden nakde dönüşmediği için dönen varlıklar arasındaki en az likit kalemlerden biridir; bu yüzden asit-test oranında hariç tutulur.'),
  ('Bir işletmenin dönen varlıkları ile kısa vadeli yabancı kaynakları arasındaki fark aşağıdakilerden hangisini ifade eder?', 'Net işletme sermayesi', ['Özsermaye kârlılığı', 'Brüt satış kârı', 'Finansal borç yükü'], 'Dönen varlıklardan kısa vadeli yabancı kaynakların çıkarılmasıyla net işletme sermayesi (net çalışma sermayesi) elde edilir.'),
  ('Toplam yabancı kaynakların (toplam borçların) toplam varlıklara (aktiflere) bölünmesiyle hesaplanan oran aşağıdakilerden hangisidir?', 'Finansal kaldıraç oranı', ['Aktif kârlılık oranı', 'Alacak devir hızı', 'Nakit likidite oranı'], 'Finansal kaldıraç oranı, varlıkların yüzde kaçının yabancı kaynaklarla (borçla) finanse edildiğini gösteren temel yapı oranıdır.'),
  ('Net dönem kârının özkaynaklara (özsermayeye) bölünmesiyle hesaplanan ve ortakların koyduğu sermayenin getirisini ölçen oran hangisidir?', 'Özkaynak kârlılığı (ROE)', ['Aktif kârlılığı (ROA)', 'Brüt kâr marjı', 'Faaliyet kâr marjı'], 'Özkaynak kârlılığı (Return on Equity - ROE), şirket sahiplerinin yatırdıkları sermaye başına elde edilen net kâr oranını gösterir.'),
  ('Sadece nakit ve nakit benzerleri ile menkul kıymetlerin kısa vadeli yabancı kaynaklara bölünmesiyle bulunan en dar kapsamlı likidite oranı hangisidir?', 'Nakit oranı', ['Cari oran', 'Stok devir oranı', 'Kaldıraç oranı'], 'Nakit oranı (hazır değerler oranı), işletmenin satış yapmadan ve alacak tahsil etmeden elindeki hazır değerlerle kısa vadeli borçlarını ne ölçüde ödeyebileceğini gösterir.'),
  ('Bir gıda perakendecisi ile bir mobilya üreticisinin likidite oranları karşılaştırıldığında gıda perakendecisinin daha düşük bir cari oranla sorunsuz çalışabilmesinin ana sebebi nedir?', 'Stoklarını çok hızlı nakde çevirmesi ve ağırlıklı olarak peşin satış yapması', ['Uzun vadeli banka kredilerine erişiminin mobilya sektörüne göre yasaklı olması', 'Maddi duran varlıkları için amortisman ayırma zorunluluğunun bulunmaması', 'Özsermaye kaleminin bilanço pasifinde yer almaması ve borçsuz çalışması'], 'Hızlı tüketim ve gıda perakendeciliğinde stoklar hızla satılıp nakit tahsil edildiği için daha düşük cari oranla likidite ihtiyacı rahatlıkla karşılanabilir.'),
  ('Nakit akış tablosunda işletmenin ana faaliyet konusundan kaynaklanan nakit giriş ve çıkışlarının izlendiği bölüm hangisidir?', 'İşletme faaliyetlerinden nakit akışları', ['Yatırım faaliyetlerinden nakit akışları', 'Finansman faaliyetlerinden nakit akışları', 'Özkaynak değişimlerinden nakit akışları'], 'Mal ve hizmet alım-satımı, tahsilatlar, tedarikçi ve personel ödemeleri gibi ana iş koluna ait nakit hareketleri işletme faaliyetlerinden nakit akışlarında raporlanır.'),
  ('Bir işletmenin faiz ve vergi öncesi kârının (FVÖK / EBIT) faiz giderlerine bölünmesiyle hesaplanan oran aşağıdakilerden hangisidir?', 'Faiz karşılama oranı', ['Nakit dönüşüm oranı', 'Net kâr marjı', 'Özsermaye çarpanı'], 'Faiz karşılama oranı, şirketin faaliyetlerinden elde ettiği kârla borçlarının faiz yükünü kaç kez karşılayabildiğini ölçer.'),
  ('Bir işletmenin cari oranının sektörel ortalamanın çok üzerinde (örneğin 6,5) olması finansal yönetim açısından hangi olumsuz duruma işaret edebilir?', 'Kaynakların düşük getirili atıl nakitte veya aşırı stokta verimsiz tutulduğuna', ['Şirketin vadesi gelen kısa vadeli borçlarını ödeme kapasitesini tamamen yitirdiğine', 'İşletmenin özkaynaklarının negatife düştüğüne ve teknik iflas yaşadığına', 'Uzun vadeli banka kredilerinin faiz oranlarının piyasa ortalamasını aştığına'], 'Aşırı yüksek cari oran likidite riskinin düşük olduğunu gösterse de kaynakların yatırıma dönüştürülmediğini, atıl nakit veya birikmiş stok bulunduğunu işaret eder.'),
  ('Net satış hasılatından yalnızca satılan malın maliyeti (SMM) çıkarıldığında ulaşılan kâr büyüklüğü aşağıdakilerden hangisidir?', 'Brüt satış kârı', ['Esas faaliyet kârı', 'Vergi öncesi kâr', 'Dönem net kârı'], 'Net satışlardan satışların maliyetinin düşülmesiyle brüt satış kârı elde edilir.'),
  ('Yeni bir fabrika binası veya üretim makinesi satın alınması nedeniyle yapılan nakit ödemeler nakit akış tablosunun hangi bölümünde yer alır?', 'Yatırım faaliyetlerinden nakit akışları', ['İşletme faaliyetlerinden nakit akışları', 'Finansman faaliyetlerinden nakit akışları', 'Olağandışı faaliyetlerden nakit akışları'], 'Maddi ve maddi olmayan duran varlık alım ve satımları yatırım faaliyetlerinden nakit akışları altında sınıflandırılır.'),
  ('Bankadan uzun vadeli nakit kredi çekilmesi veya ortaklara nakit kâr payı (temettü) dağıtılması nakit akış tablosunun hangi bölümünde raporlanır?', 'Finansman faaliyetlerinden nakit akışları', ['Yatırım faaliyetlerinden nakit akışları', 'İşletme faaliyetlerinden nakit akışları', 'Stok yönetiminden nakit akışları'], 'Borçlanma, kredi anapara geri ödemeleri, sermaye artırımı ve temettü ödemeleri finansman faaliyetlerinden nakit akışları kapsamındadır.'),
  ('Finansal kaldıraç oranının %85 gibi çok yüksek bir seviyede olması borç veren kreditörler (bankalar) açısından ne ifade eder?', 'Şirketin özkaynak tamponunun çok zayıf olduğunu ve geri ödeyememe (iflas) riskinin yüksekliğini', ['İşletmenin tüm faaliyetlerini ortakların kendi sermayesiyle ve sıfır riskle yürüttüğünü', 'Şirketin faiz giderlerinin vergi matrahından düşülemeyecek kadar küçük kaldığını', 'İşletmenin kasasında borçlarının tamamını tek seferde kapatacak hazır nakit bulunduğunu'], 'Varlıkların %85\'i borçla finanse ediliyorsa özkaynak payı yalnızca %15\'tir; olası bir zararda alacaklıları koruyan özkaynak yastığı çok incedir.'),
  ('İşletmenin esas faaliyetlerinden elde ettiği kârın net satışlara bölünmesiyle bulunan ve ana iş kolunun operasyonel verimliliğini ölçen oran hangisidir?', 'Faaliyet kâr marjı', ['Nakit karşılama oranı', 'Cari likidite oranı', 'Finansal borç oranı'], 'Faaliyet kâr marjı (Esas Faaliyet Kârı / Net Satışlar), finansman ve vergi etkilerinden bağımsız olarak ana işin kârlılığını ölçer.'),
  ('"Kâr bir muhasebe görüşüdür, nakit ise bir gerçektir" sözü finansal okuryazarlıkta aşağıdakilerden hangisini vurgular?', 'Kârın tahakkuk ve değerleme tahminlerine dayanırken nakdin fiili ödeme gücünü gösterdiğini', ['Gelir tablosu düzenlemenin yasal olarak isteğe bağlı bir uygulama olduğunu', 'Kâr eden hiçbir şirketin banka kredisi kullanmaya ihtiyaç duymayacağını', 'Bilançodaki özkaynak tutarının her zaman kasadaki nakit paraya eşit olduğunu'], 'Kâr; amortisman yöntemleri, karşılıklar ve vadeli tahakkuklardan etkilenirken nakit akışı kasaya fiilen giren ve çıkan parayı gösterir.'),
  ('Bilançoda dönen varlıklar grubunda yer alan kalemlerin sıralanmasında esas alınan temel ölçüt aşağıdakilerden hangisidir?', 'En likit olandan en az likit olana doğru sıralama', ['Tutarı en büyük olandan en küçük olana doğru sıralama', 'Satın alma tarihi en eski olandan en yeni olana sıralama', 'Yabancı para cinsinden olandan yerel paraya doğru sıralama'], 'Tekdüzen hesap planı ve finansal raporlama standartlarında aktif kalemler likidite (paraya çevrilme hızı) esasına göre sıralanır.'),
  ('Bir işletmenin günlük faaliyetlerini kesintisiz sürdürebilmesi için ihtiyaç duyduğu dönen varlık toplamına finans literatüründe ne ad verilir?', 'Brüt işletme sermayesi', ['Sabit sermaye yatırımı', 'Ödenmiş esas sermaye', 'Uzun vadeli yabancı kaynak'], 'Dönen varlıkların toplamı brüt işletme sermayesi (brüt çalışma sermayesi) olarak adlandırılır; kısa vadeli borçlar düşüldüğünde ise net işletme sermayesine ulaşılır.'),
  ('Satıcılara olan ticari borçların ödeme süresini tedarikçiyle anlaşarak vade farkı ödemeksizin 30 günden 60 güne çıkaran bir işletme nasıl bir avantaj elde eder?', 'İşletme sermayesi finansman ihtiyacını azaltarak nakdi daha uzun süre bünyesinde tutar', ['Gelir tablosundaki brüt satış kâr marjını doğrudan iki katına çıkarmış olur', 'Bilançosundaki maddi duran varlık toplamını kısa vadede ikiye katlar', 'Kısa vadeli yabancı kaynaklarını sıfırlayarak cari oranını sonsuza yükseltir'], 'Tedarikçi vadesinin maliyetsiz uzatılması bedelsiz ticari kredi niteliğindedir; nakit çıkışını geciktirerek nakit akışını rahatlatır.'),
  ('Bir işletmenin net dönem kârının net satışlara bölünmesiyle elde edilen ve her 100 birimlik satıştan geriye kaç birim net kazanç kaldığını gösteren oran hangisidir?', 'Net kâr marjı', ['Aktif kârlılık oranı', 'Alacak devir oranı', 'Özsermaye kârlılığı'], 'Net kâr marjı (Net Dönem Kârı / Net Satışlar), tüm maliyet, gider, faiz ve vergiler düşüldükten sonra satışlardan kalan nihai kâr yüzdesini verir.'),
  ('Bilançoda toplam varlıkların toplam özkaynaklara bölünmesiyle (Toplam Aktif / Özkaynak) hesaplanan ve DuPont analizinde kaldıracı temsil eden oran hangisidir?', 'Özkaynak çarpanı', ['Nakit dönüşüm oranı', 'Sabit varlık devir hızı', 'Brüt kâr marjı'], 'Toplam Aktif / Özkaynak oranı "özkaynak çarpanı" (equity multiplier) olarak adlandırılır ve borç kullanımı arttıkça büyür.'),
  ('Peşin bedelle eski üretim makinesini defter değerinden (kâr veya zarar etmeden) satan bir şirketin net işletme sermayesi nasıl değişir?', 'Satış tutarı kadar artar', ['Satış tutarı kadar azalır', 'Kâr oluşmadığı için değişmez', 'Önce azalır sonra sıfırlanır'], 'Duran varlık azalırken kasadaki nakit (dönen varlık) arttığı ve kısa vadeli borçlar değişmediği için net işletme sermayesi satış bedeli kadar artar.'),
  ('Bir şirketin yabancı kaynak (borç) kullanması sonucunda faiz giderlerini vergi matrahından düşerek daha az kurumlar vergisi ödemesine finans literatüründe ne ad verilir?', 'Vergi kalkanı', ['Nakit tamponu', 'Likidite tuzağı', 'Sermaye yedekleri'], 'Borç faizleri gider yazılarak vergiye tabi kârdan düşüldüğü için şirketin ödeyeceği vergiyi azaltır; bu avantaja "faiz vergi kalkanı" denir.'),
  ('Kısa vadeli yabancı kaynaklar bilançoda hangi vade ölçütüne göre sınıflandırılır?', 'Normal koşullarda en fazla bir yıl veya bir faaliyet dönemi içinde ödenecek borçlar', ['Sadece vadesi 30 günü aşmayan ve nakit olarak ödenecek ticari senetler', 'Kuruluş tarihinden itibaren beş yıl içinde geri ödenecek banka kredileri', 'Faiz oranı sabitlenmiş olan tüm yerli ve yabancı para cinsinden yükümlülükler'], 'Bilanço tarihinden itibaren 1 yıl (12 ay) veya normal faaliyet döngüsü içinde ödenecek yükümlülükler kısa vadeli yabancı kaynaklar altında izlenir.'),
  ('Bir işletmenin "likidite riski" taşıması aşağıdakilerden hangisiyle doğrudan ilgilidir?', 'Varlıklarını değer kaybına uğramadan zamanında nakde çeviremeyip vadesi gelen borçlarını ödeyememesiyle', ['Uzun vadeli üretim kapasitesinin rakiplerin teknolojik yeniliklerinin gerisinde kalmasıyla', 'Yönetim kurulunun ortaklara kâr payı dağıtmak yerine yedek akçe ayırma kararı almasıyla', 'Şirketin faaliyet gösterdiği ülkede kurumlar vergisi oranının bir puan indirilmesiyle'], 'Likidite riski, şirketin toplam varlıkları borçlarından fazla olsa bile vadesi gelen kısa vadeli yükümlülüklerini ödeyecek yeterli nakdi zamanında bulamamasıdır.'),
  ('Nakit akış tablosunda işletmenin nakit hareketleri hangi üç ana faaliyet grubunda sınıflandırılır?', 'İşletme, yatırım ve finansman', ['Üretim, pazarlama ve genel yönetim', 'Dönen, duran ve özkaynak hareketleri', 'Brüt satış, faaliyet ve net dönem kârı'], 'Nakit akış tablosu nakit giriş ve çıkışlarını işletme, yatırım ve finansman faaliyetleri şeklinde üç bölümde raporlar.'),
  ('Bir üretim şirketinin yeni bir fabrika makinesi satın almak için nakit ödemesi, nakit akış tablosunun hangi bölümünde yer alır?', 'Yatırım faaliyetleri', ['İşletme faaliyetlerinden nakit akışı', 'Finansman faaliyetlerinden nakit çıkışı', 'Kısa vadeli ticari borç ödemeleri'], 'Uzun vadeli maddi duran varlık alımları ve satışları yatırım faaliyetlerinden kaynaklanan nakit akışları içinde gösterilir.'),
  ('Bir şirketin bankadan uzun vadeli kredi çekmesi nakit akış tablosunun hangi faaliyet grubuna kaydedilir?', 'Finansman faaliyetleri', ['İşletme faaliyetleri nakit girişleri', 'Yatırım faaliyetleri nakit girişleri', 'Olağan dışı dönem geliri hareketleri'], 'Kredi kullanımı, borç ana para ödemesi, sermaye artırımı ve temettü dağıtımı finansman faaliyetleri kapsamındadır.'),
  ('Müşterilerden yapılan kredili satışların tahsilatı nakit akış tablosunun hangi bölümünde nakit girişi olarak gösterilir?', 'İşletme faaliyetleri', ['Yatırım faaliyetleri nakit girişi', 'Finansman faaliyetleri nakit girişi', 'Duran varlık değer artış fonu'], 'Ana faaliyet konusu mal ve hizmet satışlarından doğan tahsilatlar işletme faaliyetlerinden nakit akışına girer.'),
  ('Nakit akış tablosunda ortaklara nakit kâr payı (temettü) ödenmesi hangi faaliyet grubunda nakit çıkışı oluşturur?', 'Finansman faaliyetleri', ['İşletme faaliyetleri stok alımı', 'Yatırım faaliyetleri varlık edinimi', 'Dönem sonu amortisman gider kaydı'], 'Sermaye sahiplerine nakit temettü ödenmesi finansman faaliyetlerinden kaynaklanan bir nakit çıkışıdır.'),
  ('Bir şirketin tahvil ihraç ederek piyasadan nakit toplaması nakit akış tablosunun hangi bölümünde yer alır?', 'Finansman faaliyetleri', ['İşletme faaliyetleri nakit girişleri', 'Yatırım faaliyetleri nakit girişleri', 'Stok değerleme farkı hesabı'], 'Tahvil ihracı yoluyla borçlanma, uzun vadeli kaynak sağladığı için finansman faaliyetlerinden nakit girişi olarak sınıflandırılır.'),
  ('Başka bir şirketin hisse senetlerini uzun vadeli yatırım amacıyla satın almak nakit akış tablosunda hangi bölüme yazılır?', 'Yatırım faaliyetleri', ['İşletme faaliyetleri nakit çıkışı', 'Finansman faaliyetleri nakit çıkışı', 'Kısa vadeli gider tahakkukları'], 'Uzun vadeli finansal varlık veya iştirak hissesi alımları yatırım faaliyetlerinden nakit çıkışı kapsamında raporlanır.'),
  ('Likidite oranlarından asit-test (likidite) oranı hesaplanırken dönen varlıklardan hangi kalem çıkarılır?', 'Stoklar', ['Hazır değerler ve banka mevduatı', 'Kısa vadeli ticari alacaklar', 'Kısa vadeli banka kredileri'], 'Asit-test oranı = (Dönen Varlıklar − Stoklar) / Kısa Vadeli Yabancı Kaynaklar formülüyle en likit varlıkların kısa vadeli borçları karşılama gücünü ölçer.'),
  ('Asit-test oranının cari orana göre daha muhafazakâr bir likidite göstergesi olmasının sebebi nedir?', 'Stokların nakde dönüşme belirsizliğini dışlaması', ['Tüm uzun vadeli borçları paydaya eklemesi', 'Sadece kasa mevcudunu dikkate alması', 'Alacakları varlık toplamından tamamen çıkarması'], 'Stoklar en yavaş nakde dönen dönen varlık grubu olduğundan, bunları hariç tutan asit-test oranı daha temkinli bir ödeme gücü ölçümü sunar.'),
  ('Nakit oranı (hazır değerler oranı) pay kısmında hangi varlık grubunu dikkate alır?', 'Hazır değerler ve menkul kıymetler', ['Dönen varlıklar ve tüm ticari alacaklar', 'Maddi duran varlıklar ve stoklar', 'Toplam aktifler ve birikmiş amortismanlar'], 'Nakit oranı = (Hazır Değerler + Kısa Vadeli Menkul Kıymetler) / Kısa Vadeli Borçlar şeklinde en acil ödeme gücünü ölçer.'),
  ('Bir işletmenin toplam borçlarının özkaynaklarına bölünmesiyle elde edilen kaldıraç oranı hangisidir?', 'Borç/özkaynak oranı', ['Cari likidite karşılama oranı', 'Aktif kârlılık devir oranı', 'Brüt satış kârı marjı'], 'Borç/özkaynak oranı, işletmenin finansmanında yabancı kaynakların özkaynaklara göre ağırlığını gösteren temel sermaye yapısı oranıdır.'),
  ('Toplam borçların toplam varlıklara bölünmesiyle bulunan finansal yapı oranı hangisidir?', 'Finansal kaldıraç oranı', ['Stok devir hızı oranı', 'Alacak tahsil süresi oranı', 'Faaliyet kâr marjı oranı'], 'Toplam Borç / Toplam Varlık oranı finansal kaldıraç (borçluluk) oranı olarak adlandırılır ve varlıkların yüzde kaçının borçla finanse edildiğini gösterir.'),
  ('Stok devir hızı oranı standart finansal analizde hangi iki büyüklüğün bölünmesiyle hesaplanır?', 'Satışların maliyeti bölü ortalama stok', ['Net dönem kârı bölü dönem başı nakit', 'Toplam varlıklar bölü kısa vadeli borç', 'Faaliyet giderleri bölü ortalama alacak'], 'Stoklar maliyet bedeliyle izlendiği için stok devir hızı = Satışların Maliyeti / Ortalama Stok formülüyle hesaplanır.'),
  ('Alacak devir hızı oranı temel olarak hangi iki kalemin birbirine oranlanmasıyla hesaplanır?', 'Kredili net satışlar bölü ortalama ticari alacak', ['Satışların maliyeti bölü ortalama ticari borç', 'Toplam özkaynak bölü dönem sonu kasa', 'Faaliyet kârı bölü ortalama maddi duran varlık'], 'Alacak devir hızı, ticari alacakların bir yılda kaç kez tahsil edilip yenilendiğini ölçer ve kredili net satışların ortalama ticari alacaklara bölünmesiyle bulunur.'),
  ('Ticari alacakların tahsil süresinin yıllar içinde sürekli uzaması hangi soruna işaret edebilir?', 'Kredi ve tahsilat politikasının gevşediğine', ['Satışların tamamının peşin yapıldığına', 'Stok maliyetlerinin hızla düştüğüne', 'Sabit varlık yatırımlarının tamamlandığına'], 'Alacak tahsil süresinin uzaması, müşterilerin ödemeleri geciktirdiğini veya işletmenin tahsilat takibinde zayıfladığını gösterir.'),
  ('Üretim miktarı değiştikçe belirli bir faaliyet aralığında toplam tutarı sabit kalan maliyetlere ne ad verilir?', 'Sabit maliyet', ['Değişken üretim maliyeti', 'Birim hammadde maliyeti', 'Satış komisyonu gideri'], 'Kira, sigorta ve doğrusal amortisman gibi maliyetler ilgili kapasite aralığında üretim hacminden bağımsız olarak toplamda sabit kalır.'),
  ('Üretim hacmiyle doğru orantılı olarak toplam tutarı artan veya azalan maliyet türü hangisidir?', 'Değişken maliyet', ['Sabit genel yönetim maliyeti', 'Dönemsel fabrika kira gideri', 'Yıllık bina sigorta primi'], 'Direkt ilk madde ve malzeme ile parça başı işçilik gibi değişken maliyetlerin toplamı üretim miktarına paralel olarak değişir.'),
  ('Birim satış fiyatı ile birim değişken maliyet arasındaki fark maliyet muhasebesinde ne olarak adlandırılır?', 'Birim katkı payı', ['Birim net dönem kârı', 'Birim sabit gider yükü', 'Birim birikmiş amortisman'], 'Birim katkı payı, satılan her bir ürünün önce sabit maliyetleri karşılamaya, ardından kâr oluşturmaya sağladığı katkıyı ifade eder.'),
  ('Toplam gelirlerin toplam maliyetlere eşit olduğu, işletmenin ne kâr ne de zarar ettiği üretim/satış düzeyine ne ad verilir?', 'Başabaş noktası', ['Maksimum kapasite sınırı', 'Ekonomik sipariş miktarı', 'Marjinal fayda eşiği'], 'Başabaş noktası (kâra geçiş noktası), toplam satış hasılatının sabit ve değişken maliyetlerin toplamını tam karşıladığı noktadır.'),
  ('Hem sabit hem de değişken bileşen içeren (örneğin sabit aylık abonelik ücreti artı kullanım başına birim ücretli elektrik faturası) maliyetler nasıl adlandırılır?', 'Karma maliyet', ['Saf sabit dönem maliyeti', 'Doğrudan değişken malzeme maliyeti', 'Geri kazanılabilir batık maliyet'], 'Belirli bir sabit taban tutara ek olarak faaliyet hacmine göre artan giderlere karma (yarı değişken) maliyet denir.'),
  ('Maddi duran varlıkların kullanım, yıpranma ve teknolojik eskime nedeniyle maliyetlerinin faydalı ömürlerine gider olarak dağıtılması işlemine ne ad verilir?', 'Amortisman', ['Stok değerleme işlemi', 'Kâr payı dağıtımı', 'Ticari borç reeskontu'], 'Amortisman, bir duran varlığın edinim maliyetinin yararlanıldığı dönemlere sistematik biçimde gider olarak yansıtılmasıdır.'),
  ('Hangi maddi duran varlık grubunun faydalı ömrü sınırsız kabul edildiği için kural olarak amortisman ayrılmaz?', 'Arsa ve araziler', ['Üretim makineleri ve tesisler', 'Şirket binaları ve depolar', 'Ticari taşıtlar ve bilgisayarlar'], 'Boş arsa ve araziler kullanımla yıpranıp tükenmediği için muhasebe standartlarına göre amortismana tabi tutulmaz.'),
  ('Duran varlığın amortismana tabi maliyetinin faydalı ömrünün her yılına eşit tutarlarda gider yazıldığı yöntem hangisidir?', 'Doğrusal amortisman yöntemi', ['Azalan bakiyeler amortisman yöntemi', 'Üretim miktarı amortisman yöntemi', 'Hızlandırılmış vergi erteleme yöntemi'], 'Doğrusal (normal) amortisman yönteminde (Maliyet − Kalıntı Değer) / Faydalı Ömür tutarı her yıl eşit gider kaydedilir.'),
  ('Azalan bakiyeler (hızlandırılmış amortisman) yönteminin doğrusal yönteme göre en belirgin özelliği nedir?', 'İlk yıllarda daha yüksek amortisman gideri yazması', ['Son yılda en yüksek gider tutarını ayırması', 'Her yıl sabit tutarda gider kaydetmesi', 'Yalnızca maddi olmayan varlıklara uygulanması'], 'Azalan bakiyeler yöntemi, varlığın net defter değeri üzerinden yüksek oran uyguladığı için ilk yıllarda daha fazla, sonraki yıllarda azalan gider yazar.'),
  ('Birikmiş amortisman hesabı bilançoda hangi nitelikte bir hesap olarak sınıflandırılır?', 'Aktifi düzenleyici pasif karakterli hesap', ['Kısa vadeli ticari borç hesabı', 'Özkaynak sermaye yedekleri hesabı', 'Dönem sonu satış geliri hesabı'], 'Birikmiş amortisman bilançonun aktifinde ilgili duran varlığın altında eksi (−) işaretiyle yer alan aktifi düzenleyici bir hesaptır.'),
  ('Gelir ve giderlerin nakit tahsilatı veya ödemesi beklenmeden, doğdukları ve ilgili oldukları döneme kaydedilmesini öngören muhasebe ilkesi hangisidir?', 'Tahakkuk esası', ['Nakit esası muhasebesi', 'Maliyet bedeli varsayımı', 'İşletmenin sürekliliği ilkesi'], 'Tahakkuk esasına göre finansal işlemler paranın el değiştirdiği anda değil, ekonomik hak veya yükümlülüğün doğduğu dönemde kayda alınır.'),
  ('Nakit esasına göre tutulan bir kayıtta bir satış geliri hangi anda gelir olarak tanınır?', 'Paranın fiilen tahsil edildiği anda', ['Faturanın düzenlenip müşteriye gönderildiği anda', 'Ürünün depoda üretiminin bittiği anda', 'Müşteriyle satış sözleşmesinin imzalandığı anda'], 'Nakit esasında gelirler yalnız nakit girişi gerçekleştiğinde, giderler de yalnız nakit ödemesi yapıldığında kayda alınır.'),
  ('Temel muhasebe denklemi olarak bilinen bilanço eşitliği hangi biçimde ifade edilir?', 'Varlıklar = Borçlar + Özkaynaklar', ['Varlıklar = Gelirler + Özkaynaklar', 'Borçlar = Varlıklar + Özkaynaklar', 'Özkaynaklar = Varlıklar + Borçlar'], 'Bilanço eşitliğine göre bir işletmenin sahip olduğu tüm varlıklar (aktif), yabancı kaynaklar (borçlar) ile özkaynakların (pasif) toplamına her zaman eşittir.'),
  ('Bir işletme 40.000 TL tutarındaki malı kredili (veresiye) satın aldığında bilanço eşitliği nasıl değişir?', 'Varlıklar ve borçlar 40.000 TL artar', ['Varlıklar artar ve özkaynaklar 40.000 TL azalır', 'Sadece varlıkların kendi iç dağılımı değişir', 'Borçlar artarken özkaynaklar aynı tutarda artar'], 'Mal alımı stokları (varlık) 40.000 TL artırırken, veresiye alım ticari borçları 40.000 TL artırır ve eşitlik korunur.'),
  ('İşletmenin bankadan çektiği nakit ile aynı tutardaki ticari borcunu ödemesi bilanço toplamını nasıl etkiler?', 'Aktif ve pasif toplamı eşit tutarda azalır', ['Aktif toplamı değişmez, pasif toplamı azalır', 'Özkaynaklar tutarı borç ödemesi kadar artar', 'Toplam varlıklar borç ödemesi kadar yükselir'], 'Kasa/banka varlığı ve ticari borç aynı tutarda azaldığından bilançonun hem aktif hem pasif toplamı küçülür.'),
  ('Bilanço ile gelir tablosu arasındaki temel zaman boyutu farkı aşağıdakilerden hangisidir?', 'Bilanço belirli bir anı, gelir tablosu bir dönemi gösterir', ['Bilanço yalnız bir yılı, gelir tablosu belirli bir günü gösterir', 'Her iki tablo da yalnızca nakit tahsilatlarını raporlar', 'Bilanço kârlılığı, gelir tablosu ise yalnız borçları özetler'], 'Bilanço belirli bir tarihteki (örneğin 31 Aralık) finansal durum fotoğrafını, gelir tablosu ise belirli bir hesap dönemindeki performans akışını sunar.'),
  ('Gelir tablosunda net satışlardan satışların maliyetinin çıkarılmasıyla elde edilen ilk kâr basamağı hangisidir?', 'Brüt satış kârı', ['Faaliyet kârı veya zararı', 'Olağan vergi öncesi kâr', 'Dönem net dağıtılabilir kârı'], 'Brüt satış kârı = Net Satışlar − Satışların Maliyeti formülüyle ana ticari veya üretim faaliyetinin doğrudan kârlılığını gösterir.'),
  ('Gelir tablosunda brüt satış kârından araştırma-geliştirme, pazarlama-satış-dağıtım ve genel yönetim giderleri çıkarıldığında hangi kaleme ulaşılır?', 'Faaliyet kârı', ['Brüt ticari satış hasılatı', 'Vergi sonrası net nakit akışı', 'Dönem başı dağıtılmamış kâr'], 'Esas faaliyet giderlerinin brüt satış kârından indirilmesiyle işletmenin ana iş kolundan kazandığı faaliyet kârı (FVÖK) bulunur.'),
  ('Gelir tablosunda brüt satışlardan satıştan iadeler, satış iskontoları ve diğer indirimler düşülerek bulunan tutar hangisidir?', 'Net satışlar', ['Brüt satış kârı tutarı', 'Satışların toplam maliyeti', 'Olağan faaliyet dışı gelir'], 'İadeler ve iskontolar toplam fatura tutarından çıkarıldığında işletmenin gerçek satış hasılatı olan net satışlar elde edilir.'),
  ('Dönen varlıkların kısa vadeli yabancı kaynaklara bölünmesiyle bulunan temel likidite ölçüsü hangisidir?', 'Cari oran', ['Asit-test likidite oranı', 'Finansal kaldıraç oranı', 'Özkaynak kârlılık oranı'], 'Cari oran = Dönen Varlıklar / Kısa Vadeli Borçlar olup işletmenin bir yıl içindeki borçlarını dönen varlıklarıyla karşılama kapasitesini ölçer.'),
  ('Dönem net kârının net satışlara bölünmesiyle hesaplanan kârlılık oranı hangisidir?', 'Net kâr marjı', ['Brüt satış kârı marjı', 'Aktif kârlılık oranı', 'Faaliyet giderleri oranı'], 'Net kâr marjı, elde edilen her 1 TL\'lik satış gelirinden tüm maliyetler, faiz ve vergiler düşüldükten sonra ne kadar net kâr kaldığını gösterir.'),
  ('Maddi olmayan duran varlıkların (patent, telif hakkı, yazılım lisansı) maliyetlerinin faydalı ömürlerine gider olarak dağıtılmasına ne ad verilir?', 'İtfa payı', ['Maddi varlık yeniden değerlemesi', 'Kısa vadeli alacak karşılığı', 'Genel üretim gideri yansıtması'], 'Maddi duran varlıklar için amortisman kavramı kullanılırken, maddi olmayan duran varlıkların giderleştirilmesi itfa (amortization) olarak adlandırılır.'),
  ('Doğal kaynakların (maden ocakları, petrol kuyuları, ormanlar) çıkarılıp tüketilmesine bağlı olarak maliyetlerinin giderleştirilmesine ne ad verilir?', 'Tükenme payı', ['Doğrusal itfa payı yöntemi', 'Ticari stok değer düşüklüğü', 'Gelecek dönem gider tahakkuku'], 'Doğal kaynakların fiziki olarak eksilmesi sonucu ayrılan gider payı tükenme payı (depletion) şeklinde muhasebeleştirilir.'),
  ('Aşağıdakilerden hangisi bilançoda "dönen varlıklar" grubunda yer almaz?', 'Fabrika binası', ['Ticari mallar ve stoklar', 'Kasa ve banka mevduatları', 'Kısa vadeli ticari alacaklar'], 'Dönen varlıklar bir yıl veya bir faaliyet döngüsü içinde nakde çevrilebilen kalemlerdir; fabrika binası ise maddi duran varlıktır.'),
  ('Bilançonun pasif tarafında yer alan ve bir yıl içinde ödenmesi gereken yükümlülükler hangi ana grupta toplanır?', 'Kısa vadeli yabancı kaynaklar', ['Uzun vadeli finansal yatırımlar', 'Maddi olmayan duran varlıklar', 'Ödenmiş sermaye ve yedekler'], 'Ticari borçlar, ödenecek vergiler ve bir yıl vadeli krediler kısa vadeli yabancı kaynaklar grubunda izlenir.'),
  ('Stok değerleme yöntemlerinden "İlk Giren İlk Çıkar" (FIFO) yönteminde, dönem sonunda depoda kaldığı varsayılan mallar hangileridir?', 'En son satın alınan veya üretilen mallar', ['En eski tarihte depoya giren mallar', 'Birim maliyeti en düşük olan mallar', 'Birim maliyeti aritmetik ortalama olan mallar'], 'FIFO yönteminde önce alınan malların önce satıldığı kabul edildiğinden dönem sonu stokları en güncel maliyetli son alımlardan oluşur.'),
  ('Şüpheli hâle gelen ticari alacaklar için dönem sonunda karşılık ayrılması hangi muhasebe ilkesinin doğrudan bir uygulamasıdır?', 'İhtiyatlılık kavramı', ['Parayla ölçülme varsayımı', 'Dönemsellik dışı nakit esası', 'Tam sermaye maliyeti ilkesi'], 'Tahsil olasılığı zayıflayan alacaklar için karşılık gideri ayırmak, varlıkları olduğundan yüksek göstermemek amacıyla ihtiyatlılık ilkesine dayanır.'),
  ('İşletmenin faaliyetlerini belirli bir sona erme niyeti olmaksızın öngörülebilir gelecekte de sürdüreceği kabulü hangi temel muhasebe varsayımıdır?', 'İşletmenin sürekliliği', ['Kişilik ayrımı kavramı', 'Tutarlılık muhasebe ilkesi', 'Maliyet esası yaklaşımı'], 'İşletmenin sürekliliği varsayımı, varlıkların tasfiye değeri yerine tarihî maliyet/faaliyet değeriyle izlenmesinin ve amortisman ayrılmasının temelini oluşturur.'),
  ('İşletmenin sahibinin kişisel varlık ve harcamalarının işletmenin muhasebe kayıtlarından ayrı tutulmasını zorunlu kılan temel kavram hangisidir?', 'Kişilik kavramı', ['Sosyal sorumluluk kavramı', 'Önemlilik derecesi kavramı', 'Tam açıklama sunum ilkesi'], 'Kişilik kavramı uyarınca işletme, sahiplerinden ve yöneticilerinden bağımsız ayrı bir ekonomik birim olarak muhasebeleştirilir.'),
  ('İki ya da daha fazla finansal tablo kaleminin birbirine oranlanması yerine, her kalemin aynı tablo içindeki ana toplama (örneğin satışlara veya aktif toplamına) yüzdesel oranını inceleyen analiz tekniği hangisidir?', 'Dikey analiz', ['Yatay karşılaştırmalı analiz', 'Eğilim yüzdeleri (trend) analizi', 'Başabaş noktası duyarlılık analizi'], 'Dikey analizde bilançoda tüm kalemler aktif/pasif toplamının, gelir tablosunda ise tüm kalemler net satışların yüzdesi olarak ifade edilir.'),
  ('Bir şirketin ardışık iki döneme ait finansal tablolarındaki kalemlerin tutar ve yüzde değişimlerini inceleyen analiz yöntemi hangisidir?', 'Yatay analiz', ['Dikey yüzdesel yapı analizi', 'Oran (rasyo) değerlendirme analizi', 'Standart maliyet sapma analizi'], 'Yatay analiz, farklı dönemlere ait aynı kalemleri yan yana koyarak büyüme veya daralma değişimlerini ortaya koyar.'),
  ('Aşağıdakilerden hangisi üretim işletmelerinde bir ürünün doğrudan üretim maliyetini oluşturan üç temel maliyet unsurundan biri değildir?', 'Pazarlama satış giderleri', ['Direkt ilk madde ve malzeme', 'Direkt işçilik maliyetleri', 'Genel üretim giderleri'], 'Üretim maliyeti direkt ilk madde-malzeme, direkt işçilik ve genel üretim giderlerinden oluşur; pazarlama giderleri dönem (faaliyet) gideridir.'),
  ('İki farklı alternatiften birini seçerken vazgeçilen en iyi diğer alternatifin getirisini ifade eden ekonomik maliyet kavramı hangisidir?', 'Fırsat maliyeti', ['Batık geçmiş maliyeti', 'Standart hammadde maliyeti', 'Sabit kira dönem maliyeti'], 'Fırsat (alternatif) maliyeti muhasebe defterlerinde yer almaz ancak yatırım ve üretim kararlarında gerçek ekonomik maliyeti gösterir.'),
  ('Borsada işlem gören bir şirketin hisse başına piyasa fiyatının hisse başına kârına (HBK) bölünmesiyle elde edilen değerleme oranı hangisidir?', 'Fiyat/Kazanç (F/K) oranı', ['Piyasa Değeri/Defter Değeri oranı', 'Borç/Özkaynak kaldıraç oranı', 'Cari likidite karşılama oranı'], 'Fiyat/Kazanç (P/E) oranı, yatırımcıların şirketin 1 TL\'lik yıllık net kârı için hisse başına kaç TL ödemeye razı olduğunu gösterir.'),
  ('İşletmenin faiz, vergi, amortisman ve itfa payları öncesi operasyonel kârlılığını ifade eden yaygın finansal gösterge hangisidir?', 'FAVÖK', ['Net dağıtılabilir dönem kârı', 'Brüt ticari mal satış tutarı', 'Toplam özsermaye kârlılığı'], 'FAVÖK (Faiz, Amortisman ve Vergi Öncesi Kâr), farklı sermaye ve amortisman yapısına sahip şirketlerin ana operasyonel nakit üretme gücünü kıyaslamak için kullanılır.'),
  ('Bir işletmenin kasasında bulunan 25.000 TL\'yi bankadaki vadesiz ticari mevduat hesabına yatırması toplam varlıklarını nasıl değiştirir?', 'Toplam varlıklar değişmez', ['Toplam varlıklar 25.000 TL artar', 'Toplam varlıklar 25.000 TL azalır', 'Özkaynaklar 25.000 TL yükselir'], 'Kasa hesabı 25.000 TL azalırken banka hesabı 25.000 TL artar; her ikisi de dönen varlık olduğundan toplam varlık tutarı sabit kalır.'),
  ('Çift taraflı kayıt (muzaaf muhasebe) sisteminde her yevmiye kaydı için geçerli olan temel kural nedir?', 'Borç toplamı alacak toplamına eşittir', ['Varlık toplamı gelir toplamına eşittir', 'Nakit girişi her zaman nakit çıkışına eşittir', 'Gider hesabı her zaman alacak tarafına yazılır'], 'Çift taraflı kayıt sisteminde her işlem en az iki hesabı etkiler ve borçlandırılan tutarların toplamı alacaklandırılan tutarların toplamına her zaman eşit olur.'),
  ('İşletmedeki mali nitelikli işlemlerin tarih sırasına göre ilk kaydedildiği defter hangisidir?', 'Yevmiye defteri (günlük defter)', ['Büyük defter (defter-i kebir)', 'Envanter ve bilanço defteri', 'Yardımcı stok takip kartı'], 'Tüm muhasebe olayları kronolojik olarak önce yevmiye defterine işlenir, ardından hesap bazında büyük deftere aktarılır.'),
  ('Büyük defter (defter-i kebir) hesaplarının belirli aralıklarla borç ve alacak toplamlarının eşitliğini kontrol etmek için düzenlenen özet çizelge hangisidir?', 'Mizan', ['Nakit akış tablosu', 'Özkaynak değişim tablosu', 'Kâr dağıtım tablosu'], 'Mizan, büyük defterdeki tüm hesapların borç-alacak toplamlarını ve bakiyelerini bir araya getirerek kayıt denkliğini denetleyen özet tablodur.'),
  ('Nakit akış tablosunda "nakit ve nakit benzerleri" kavramı kasa ve vadesiz mevduatın yanında genellikle hangi kısa vadeli yatırımları kapsar?', 'Vadesi üç ay veya daha kısa yüksek likit yatırımlar', ['Beş yıl vadeli devlet tahvili yatırımları', 'Borsada tutulan uzun vadeli iştirak hisseleri', 'Müşterilerden alınan dokuz ay vadeli senetler'], 'TFRS/UMS 7\'ye göre nakit benzerleri, tutarı belirli nakde kolayca çevrilebilen ve vadesi edinim tarihinden itibaren genellikle 3 ay veya daha kısa olan düşük riskli yatırımlardır.'),
  ('Temel muhasebe eşitliği olarak bilinen bilanço denkliği aşağıdakilerden hangisidir?', 'Varlıklar = Borçlar + Özkaynaklar', ['Varlıklar + Borçlar = Özkaynaklar Toplamı', 'Dönen Varlıklar = Kısa Vadeli Borçlar + Gelirler', 'Özkaynaklar = Toplam Varlıklar + Toplam Borçlar'], 'Temel bilanço eşitliğine göre işletmenin tüm varlıkları, borçlar (yabancı kaynaklar) ve özkaynakların toplamına eşittir.'),
  ('Çift taraflı kayıt yönteminde bir muhasebe işleminin önce tarih sırasıyla kaydedildiği defter hangisidir?', 'Yevmiye defteri', ['Büyük defter', 'Genel geçici mizan tablosu', 'Envanter ve bilanço defteri'], 'İşlemler kronolojik olarak ilk önce yevmiye (günlük) defterine, ardından hesap bazında büyük deftere aktarılır.'),
  ('Büyük defter (Defter-i Kebir) hangi temel işlevi yerine getirir?', 'İşlemleri hesap türlerine göre sınıflandırır', ['Finansal olayları yalnızca tarih sırasıyla listeler', 'Dönem sonunda nakit akış tablosunu otomatik oluşturur', 'Vergi matrahını yasal oranlara göre hesaplar'], 'Büyük defter, yevmiye defterine tarih sırasıyla girilen kayıtları ilgili hesaplara (kasa, banka, borçlar gibi) dağıtarak sınıflandırır.'),
  ('Bir işletmede varlık (aktif) hesaplarındaki artışlar, çift taraflı kayıt kurallarına göre hesabın hangi tarafına yazılır?', 'Borç tarafına', ['Alacak tarafına kaydedilir', 'Dönem sonu kapanış bölümüne', 'Yalnızca özkaynaklar bölümüne'], 'Varlık hesapları borç karakterlidir; dolayısıyla varlık artışı hesabın borç (sol) tarafına, azalışı alacak (sağ) tarafına kaydedilir.'),
  ('Borç (yabancı kaynak) ve özkaynak hesaplarındaki artışlar hangi tarafa kaydedilir?', 'Alacak tarafına', ['Borç tarafına kaydedilir', 'Gelir tablosunun gider sütununa', 'Yalnızca kasa hesabının borcuna'], 'Pasif (kaynak) hesapları alacak karakterli olduğundan, borç ve özkaynak artışları bu hesapların alacak tarafına işlenir.'),
  ('Muhasebede yevmiye defterinden büyük deftere aktarılan kayıtların matematiksel doğruluğunu kontrol eden özet çizelgeye ne ad verilir?', 'Mizan', ['Bilanço tablosu', 'Gelir ve kâr tablosu', 'Nakit akış çizelgesi'], 'Mizan, büyük defterdeki tüm hesapların borç ve alacak toplamları ile kalanlarını göstererek aktarım hatalarını denetler.'),
  ('Bir işletme bankadan çektiği nakdi kasasına koyduğunda temel bilanço eşitliği nasıl etkilenir?', 'Toplam varlık değişmez', ['Toplam varlıklar aynı tutarda artar', 'Toplam borçlar aynı tutarda azalır', 'Özkaynaklar tutarı aynı oranda yükselir'], 'Kasa artarken banka bakiyesi aynı tutarda azaldığından, iki varlık hesabı arasında yer değişimi olur ve toplam varlık sabit kalır.'),
  ('Bilançonun belirli bir tarihteki finansal durumu göstermesine karşılık, belirli bir dönemdeki gelir ve giderleri özetleyen tablo hangisidir?', 'Gelir tablosu', ['Mizan çizelgesi', 'Yevmiye defteri', 'Sermaye değişim raporu'], 'Bilanço belirli bir anın fotoğrafı iken, gelir tablosu belli bir hesap döneminin (örneğin bir yılın) faaliyet performansını gösterir.'),
  ('Bir yıl veya normal faaliyet dönemi içinde nakde çevrilmesi ya da tüketilmesi beklenen varlıklara ne ad verilir?', 'Dönen varlıklar', ['Duran varlıklar grubu', 'Uzun vadeli yabancı kaynaklar', 'Maddi olmayan duran varlıklar'], 'Nakit, kısa vadeli alacaklar ve stoklar gibi bir yıl içinde paraya dönüşebilen kalemler dönen varlıklar altında sınıflandırılır.'),
  ('Aşağıdakilerden hangisi bilançoda duran varlıklar grubunda yer alır?', 'Üretim makineleri', ['Müşterilerden kısa vadeli alacaklar', 'Satışa hazır ticari mallar', 'Vadesiz banka mevduatları'], 'Bir yıldan uzun süre işletme faaliyetlerinde kullanılmak amacıyla edinilen üretim makineleri maddi duran varlıktır.'),
  ('Aşağıdaki kalemlerden hangisi bir işletmenin kısa vadeli yabancı kaynakları arasında bulunur?', 'Vadesi altı ay olan banka kredisi', ['Şirket ortaklarının koyduğu sermaye', 'Beş yıl vadeli çıkarılmış tahviller', 'Fabrika binasının birikmiş amortismanı'], 'Ödeme süresi bir yılın altında olan banka kredileri kısa vadeli yabancı kaynak (kısa vadeli borç) olarak sınıflandırılır.'),
  ('Stok değerlemesinde FIFO yönteminin Türkçe açılımı aşağıdakilerden hangisidir?', 'İlk giren ilk çıkar', ['Son giren ilk çıkar yöntemi', 'Ağırlıklı ortalama maliyet yöntemi', 'Standart sabit birim maliyet yöntemi'], 'FIFO (First-In, First-Out), işletme deposuna en eski tarihte giren stokların ilk önce satıldığını varsayan değerleme yöntemidir.'),
  ('Stok değerlemesinde LIFO yöntemi hangi maliyet akışı varsayımına dayanır?', 'En son alınan stokların ilk satıldığına', ['En eski tarihli stokların ilk satıldığına', 'Tüm stokların sıfır maliyetle alındığına', 'Stokların yalnızca piyasa fiyatıyla çıktığına'], 'LIFO (Last-In, First-Out - Son Giren İlk Çıkar), en son satın alınan partilerin maliyetini önce satılan malın maliyetine aktarır.'),
  ('Ağırlıklı ortalama maliyet yöntemi birim stok maliyetini nasıl hesaplar?', 'Toplam maliyeti toplam miktara bölerek', ['En yüksek ve en düşük fiyatı toplayarak', 'Yalnızca son satın alınan partiyi baz alarak', 'Dönem başı stok fiyatını sabit tutarak'], 'Ağırlıklı ortalama yönteminde satılabilir toplam mal maliyeti toplam birim adedine bölünerek ortalama birim maliyet elde edilir.'),
  ('Aşağıdaki varlıklardan hangisi için muhasebe ilkelerine göre kural olarak amortisman ayrılmaz?', 'Boş arsa ve araziler', ['Fabrika binaları ve depolar', 'Üretim hattı makineleri', 'Dağıtım yapan ticari araçlar'], 'Boş arsa ve arazilerin faydalı ömrü sınırsız kabul edildiğinden yıpranma payı (amortisman) ayrılmaz.'),
  ('Bir duran varlığın maliyetinin her yıl eşit tutarlarda giderleştirildiği amortisman yöntemine ne ad verilir?', 'Normal (doğrusal) amortisman', ['Azalan bakiyeler amortisman yöntemi', 'Fevkalade (olağanüstü) amortisman', 'Üretim miktarına bağlı amortisman'], 'Doğrusal (normal) amortisman yönteminde varlığın amortismana tabi tutarı faydalı ömür yılına bölünerek her yıl eşit pay ayrılır.'),
  ('Patent, telif hakkı, ticari marka ve yazılım lisansı gibi fiziksel varlığı olmayan uzun vadeli haklar bilançoda hangi grupta yer alır?', 'Maddi olmayan duran varlıklar', ['Dönen varlıklar içindeki stoklar', 'Maddi duran varlıklar grubu', 'Uzun vadeli mali borçlar'], 'Fiziksel niteliği bulunmayan ancak işletmeye uzun vadeli ekonomik fayda sağlayan haklar maddi olmayan duran varlıklarda izlenir.'),
  ('Dönen varlıkları 450.000 TL ve kısa vadeli borçları 300.000 TL olan bir işletmenin cari oranı kaçtır?', '1,50', ['0,67 olarak hesaplanır', '2,00 seviyesindedir', '1,25 düzeyindedir'], 'Cari oran = Dönen Varlıklar / Kısa Vadeli Borçlar = 450.000 / 300.000 = 1,50 bulunur.'),
  ('Nakit dönüşüm süresini (işletme sermayesi döngüsünü) oluşturan üç temel bileşen aşağıdakilerden hangisidir?', 'Stokta kalma, alacak tahsil ve borç ödeme süresi', ['Cari oran, asit-test oranı ve nakit oranı', 'Brüt kâr, faaliyet kârı ve net kâr marjı', 'Amortisman, vergi ve finansman giderleri'], 'Nakit dönüşüm süresi = Stokta Kalma Süresi + Alacak Tahsil Süresi - Ticari Borç Ödeme Süresi şeklinde hesaplanır.'),
  ('Bir işletmenin toplam gelirlerinin toplam maliyetlerine eşit olduğu, yani ne kâr ne de zarar ettiği satış düzeyine ne ad verilir?', 'Başabaş noktası', ['Marjinal fayda noktası', 'Optimal kaldıraç eşiği', 'Net bugünkü değer sıfırı'], 'Başabaş (kâra geçiş) noktasında toplam hasılat sabit ve değişken maliyetlerin toplamını tam olarak karşılar, kâr sıfırdır.'),
  ('Üretim veya satış miktarından bağımsız olarak belirli bir kapasite aralığında değişmeyen kira ve sigorta gibi maliyetlere ne ad verilir?', 'Sabit maliyetler', ['Değişken maliyet kalemleri', 'Doğrudan hammadde giderleri', 'Satışa bağlı komisyon maliyetleri'], 'Sabit maliyetler üretim hacmi sıfır olsa bile kısa dönemde değişmeyen giderlerdir.'),
  ('Brüt satış kârının net satışlara bölünmesiyle elde edilen kârlılık oranı aşağıdakilerden hangisidir?', 'Brüt kâr marjı', ['Net satış kâr marjı', 'Özsermaye kârlılık oranı', 'Aktif kârlılık oranı'], 'Brüt kâr marjı = (Brüt Kâr / Net Satışlar) formülüyle hesaplanır ve üretim veya mal tedarik verimliliğini gösterir.'),
  ('Dönem net kârının net satışlara oranı olarak tanımlanan gösterge hangisidir?', 'Net kâr marjı', ['Faaliyet kâr marjı oranı', 'Brüt kâr marjı yüzdesi', 'FAVÖK marjı yüzdesi'], 'Net kâr marjı, her 100 TL\'lik net satışın tüm maliyetler, faiz ve vergilerden sonra ne kadar net kâr bıraktığını ölçer.'),
  ('Finansal analizde sık kullanılan FAVÖK (EBITDA) kısaltmasının Türkçe açılımı aşağıdakilerden hangisidir?', 'Faiz, Amortisman ve Vergi Öncesi Kâr', ['Finansman, Alacak ve Vergi Öncesi Kâr', 'Faaliyet, Aktif ve Varlık Öncesi Kâr', 'Fiyat, Amortisman ve Verimlilik Öncesi Kâr'], 'FAVÖK (EBITDA), işletmenin esas faaliyetlerinden finansman yapısı, vergi rejimi ve amortisman politikalarından arındırılmış kazancını ölçer.'),
  ('Aktif kârlılığı (ROA - Return on Assets) hangi formülle hesaplanır?', 'Net Kâr / Toplam Varlıklar', ['Net Kâr / Toplam Özkaynaklar', 'Brüt Kâr / Kısa Vadeli Borçlar', 'Net Satışlar / Toplam Varlıklar'], 'Aktif kârlılığı (ROA), işletmenin sahip olduğu her bir TL\'lik varlık ile ne kadar net kâr üretebildiğini ölçer.'),
  ('Özsermaye kârlılığı (ROE - Return on Equity) işletme sahipleri açısından neyi ifade eder?', 'Ortakların koyduğu sermayenin net getirisini', ['Toplam borçların bankalara ödenme hızını', 'Stokların bir yıl içinde kaç kez satıldığını', 'Şirketin kısa vadeli likidite tamponunu'], 'ROE (Net Kâr / Özkaynaklar), şirket ortaklarının işletmede tuttuğu özkaynak üzerinden elde ettiği kâr oranını gösterir.'),
  ('Bir işletmenin toplam borçlarının toplam varlıklarına oranı aşağıdakilerden hangisini ölçer?', 'Finansal kaldıraç (borç) oranını', ['Kısa vadeli likidite oranını', 'Brüt satış kâr marjını', 'Aktif devir hızı katsayısını'], 'Finansal kaldıraç oranı (Toplam Borç / Toplam Varlık), işletme varlıklarının yüzde kaçının yabancı kaynaklarla finanse edildiğini gösterir.'),
  ('Bir işletmenin belirli bir dönemdeki nakit giriş ve çıkışlarını işletme, yatırım ve finansman faaliyetleri şeklinde sınıflandıran tablo hangisidir?', 'Nakit akış tablosu', ['Genel geçici mizan tablosu', 'Bilanço varlık dökümü', 'Satışların maliyeti tablosu'], 'Nakit akış tablosu nakdin kaynağını ve kullanım alanını işletme, yatırım ve finansman olmak üzere üç ana başlıkta raporlar.'),
  ('Bir üretim şirketinin yeni bir fabrika makinesi satın almak için yaptığı nakit ödeme, nakit akış tablosunda hangi faaliyet grubunda gösterilir?', 'Yatırım faaliyetlerinden nakit akışları', ['İşletme faaliyetlerinden nakit akışları', 'Finansman faaliyetlerinden nakit akışları', 'Dönem sonu kâr dağıtım akışları'], 'Duran varlık (makine, bina, ekipman) alım ve satımları yatırım faaliyetlerinden kaynaklanan nakit akışlarında izlenir.'),
  ('Finansal tablo analizinde bir işletmenin aynı kalemlerinin birden fazla yıl boyunca gösterdiği değişim yüzdelerini inceleyen tekniğe ne ad verilir?', 'Yatay (karşılaştırmalı) analiz', ['Dikey (yüzde) analiz tekniği', 'Başabaş noktası analizi', 'DuPont çarpan ayrıştırması'], 'Yatay analiz, gelir tablosu veya bilanço kalemlerinin yıllar itibarıyla artış veya azalış yönünü ve hızını karşılaştırır.'),
  ('Bilançoda her bir kalemin toplam aktiflere, gelir tablosunda ise her kalemin net satışlara oranlanarak yüzde olarak ifade edildiği analiz tekniği hangisidir?', 'Dikey analiz', ['Yatay karşılaştırmalı analiz', 'Eğilim (trend) yüzdeleri analizi', 'Nakit dönüşüm süresi analizi'], 'Dikey analiz, tablo içi yapısal ağırlıkları gösterir ve farklı büyüklükteki şirketlerin kıyaslanmasını kolaylaştırır.'),
  ('Halka açık şirketlerde bir hisse senedinin piyasa fiyatının hisse başına kâra (HBK) bölünmesiyle bulunan piyasa çarpanı hangisidir?', 'Fiyat / Kazanç (F/K) oranı', ['Piyasa Değeri / Defter Değeri oranı', 'Firma Değeri / FAVÖK çarpanı', 'Temettü verimi yüzdesi oranı'], 'F/K oranı, yatırımcıların şirketin her 1 TL\'lik yıllık net kârı için kaç TL ödemeye razı olduğunu gösteren temel değerleme çarpanıdır.'),
  ('İşletme sahiplerinin geçmiş yıllardan biriktirip dağıtmadığı ve şirkette bıraktığı kârlar bilançonun hangi bölümünde izlenir?', 'Özkaynaklar', ['Dönen varlıklar içindeki nakitler', 'Uzun vadeli yabancı kaynaklar', 'Maddi olmayan duran varlıklar'], 'Dağıtılmamış kârlar (geçmiş yıllar kârları ve yedek akçeler), işletme ortaklarına ait olduğundan bilançoda özkaynaklar altında yer alır.'),
  ('İşletmenin ömrünün sahiplerinin yaşam süresine bağlı olmadığı ve öngörülebilir gelecekte faaliyetlerini sürdüreceği varsayımına dayanan muhasebe kavramı hangisidir?', 'İşletmenin sürekliliği', ['Kişilik kavramı ilkesi', 'Sosyal sorumluluk kavramı', 'Özün önceliği ilkesi'], 'Süreklilik kavramı sayesinde varlıklar tasfiye değerinden değil, normal faaliyet koşullarına göre (örneğin amortismana tabi tutularak) değerlenir.'),
  ('İşletme sahibinin şahsi ev harcamalarının şirket muhasebesine gider olarak kaydedilmemesini zorunlu kılan temel ilke hangisidir?', 'Kişilik kavramı', ['Dönemsellik kavramı ilkesi', 'Tutarlılık kavramı ilkesi', 'Tam açıklama kavramı'], 'Kişilik kavramı, işletmenin ortaklarından ve yöneticilerinden ayrı bağımsız bir ekonomik kişiliğe sahip olduğunu vurgular.'),
  ('Bir işletmenin elindeki nakit ve menkul kıymetlerle (alacakları ve stokları beklemeden) kısa vadeli borçlarını ödeme gücünü ölçen en katı likidite rasyosu hangisidir?', 'Nakit oranı', ['Cari likidite oranı', 'Asit-test oranı', 'Stok devir oranı'], 'Nakit Oranı = (Nakit ve Nakit Benzerleri + Menkul Kıymetler) / Kısa Vadeli Borçlar şeklinde hesaplanır.'),
];
